"""API Endpoint Permission Canonicalizer.

Reads /app/input.txt and writes the canonical permission configuration
to /app/output.txt.
"""

import re

INPUT_PATH = "/app/input.txt"
OUTPUT_PATH = "/app/output.txt"

VALID_METHODS = {"GET", "POST", "PUT", "DELETE", "PATCH"}
VALID_PERMISSIONS = {"ALLOW", "DENY"}
ROLE_RE = re.compile(r"^[A-Za-z0-9_-]+$")
VAR_RE = re.compile(r"\{[A-Za-z0-9_-]+\}")


def normalize_path(path):
    """Replace valid {variable} patterns with {var} for matching."""
    return VAR_RE.sub("{var}", path)


def count_segments(path):
    """Number of non-empty segments when splitting on '/'."""
    return len([s for s in path.split("/") if s])


def is_prefix(parent, child):
    """True if parent normalized path is a (strict) prefix of child."""
    return child.startswith(parent) and child != parent


def parse_endpoint_line(line):
    """Parse one ENDPOINTS line. Returns dict or None if malformed."""
    parts = line.split()
    if len(parts) != 4:
        return None
    path, method, role, permission = parts
    if path == "":
        return None
    method = method.upper()
    if method not in VALID_METHODS:
        return None
    permission = permission.upper()
    if permission not in VALID_PERMISSIONS:
        return None
    if role == "" or not ROLE_RE.match(role):
        return None
    return {
        "path": path,
        "npath": normalize_path(path),
        "method": method,
        "role": role,
        "permission": permission,
    }


def parse_plan_line(line):
    """Parse one PLAN line. Returns (path, method) or None if malformed."""
    parts = line.split()
    if len(parts) != 2:
        return None
    path, method = parts
    if path == "":
        return None
    method = method.upper()
    if method not in VALID_METHODS:
        return None
    return (path, method)


def split_sections(text):
    """Split file text into sections on blank lines."""
    sections = []
    current = []
    for line in text.split("\n"):
        if line.strip() == "":
            if current:
                sections.append(current)
                current = []
        else:
            current.append(line)
    if current:
        sections.append(current)
    return sections


def main():
    with open(INPUT_PATH, "r") as f:
        text = f.read()

    sections = split_sections(text)

    # ---- ENDPOINTS section (with hard cutoff) ----
    endpoints = []
    if sections:
        for line in sections[0]:
            ep = parse_endpoint_line(line)
            if ep is None:
                break  # hard cutoff
            endpoints.append(ep)

    # ---- BASE/EXCLUDE section ----
    base = None
    excluded_roles = set()
    if len(sections) >= 2:
        for line in sections[1]:
            parts = line.split()
            if not parts:
                continue
            if parts[0] == "base" and len(parts) >= 2:
                base = parts[1]
            elif parts[0] == "exclude":
                for r in parts[1:]:
                    excluded_roles.add(r)

    # ---- PLAN section (with hard cutoff) ----
    plan = []
    if len(sections) >= 3:
        for line in sections[2]:
            pm = parse_plan_line(line)
            if pm is None:
                break  # hard cutoff
            plan.append(pm)

    # ---- Eligibility: base prefix filter ----
    def base_ok(path):
        if base is None:
            return True
        return path.startswith(base)

    eligible = [ep for ep in endpoints if base_ok(ep["path"])]
    eligible_npaths = {ep["npath"] for ep in eligible}

    # ---- Determine which normalized paths are needed ----
    plan_npaths = []
    for path, _method in plan:
        np_ = normalize_path(path)
        if np_ not in eligible_npaths:
            continue  # endpoints in PLAN not in ENDPOINTS are ignored
        plan_npaths.append(np_)

    if plan:
        needed = set(plan_npaths)
        # Parent path resolution for each planned endpoint
        for target in plan_npaths:
            for p in eligible_npaths:
                if is_prefix(p, target):
                    needed.add(p)
    else:
        # Empty PLAN: all eligible endpoints (excluded roles filtered out)
        needed = set(eligible_npaths)

    # ---- Select endpoints ----
    selected = []
    for ep in eligible:
        if ep["npath"] not in needed:
            continue
        if ep["role"] in excluded_roles:
            # Special case: included only if the parent path has endpoints
            # ONLY for excluded roles (needed for inheritance resolution).
            siblings = [e for e in eligible if e["npath"] == ep["npath"]]
            if all(s["role"] in excluded_roles for s in siblings):
                selected.append(ep)
            # otherwise filtered out
        else:
            selected.append(ep)

    # ---- Deduplicate: first (path, method, role) by input order ----
    seen = set()
    deduped = []
    for ep in selected:
        key = (ep["path"], ep["method"], ep["role"])
        if key in seen:
            continue
        seen.add(key)
        deduped.append(ep)

    # ---- Order: segments desc, method alpha, role lexicographic,
    #      permission (ALLOW before DENY) ----
    def sort_key(ep):
        return (
            -count_segments(ep["path"]),
            ep["method"],
            ep["role"],
            0 if ep["permission"] == "ALLOW" else 1,
        )

    deduped.sort(key=sort_key)

    # ---- Output ----
    lines = [
        "{} {} {} {}".format(ep["path"], ep["method"], ep["role"], ep["permission"])
        for ep in deduped
    ]
    out = "\n".join(lines) + "\n"
    with open(OUTPUT_PATH, "w") as f:
        f.write(out)


if __name__ == "__main__":
    main()
